import csv
from collections import defaultdict, Counter

def parse_month_year(s):
    s=(s or '').strip()
    if not s:
        return None
    try:
        mon, year = s.split('-')
    except ValueError:
        return None
    mon_map={'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}
    if mon=='Unknown':
        return None
    if mon not in mon_map:
        return None
    return (int(year), mon_map[mon])

rows=[]
with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for r in reader:
        rows.append(r)

# counts by month for major_topic using month_year parsing
counts=defaultdict(Counter)
months=set()
for r in rows:
    k=parse_month_year(r.get('month_year'))
    if not k:
        continue
    months.add(k)
    topic=(r.get('major_topic') or '').strip()
    if not topic:
        continue
    counts[topic][k]+=1

months=sorted(months)
print('months', len(months), months[:3], months[-3:])

# compute MoM % growth over last 6 transitions, using topics with enough volume
last=months[-1]
# build last 9 months for robust
last9=[]
y,m=last
for _ in range(9):
    last9.append((y,m))
    m-=1
    if m==0:
        y-=1
        m=12
last9=sorted(last9)

# growth metric: average MoM growth rate over last 6 steps where prev>0
scores=[]
for topic,c in counts.items():
    vals=[c.get(k,0) for k in last9]
    if sum(vals)<8:
        continue
    growths=[]
    for i in range(1,len(vals)):
        prev=vals[i-1]
        curr=vals[i]
        if prev==0:
            continue
        growths.append((curr-prev)/prev)
    if len(growths)<3:
        continue
    avg=sum(growths)/len(growths)
    scores.append((avg, sum(vals), topic, vals))

scores.sort(reverse=True)
print('candidates', len(scores))
for avg, tot, topic, vals in scores[:10]:
    print(topic, 'avg_mom', round(avg,2), 'tot_last9', tot, 'vals', vals)
