import csv
from collections import defaultdict, Counter

def parse_month_year(s):
    s=(s or '').strip()
    if not s:
        return None
    try:
        mon, year = s.split('-')
    except ValueError:
        return None
    mon_map={'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}
    if mon=='Unknown':
        return None
    if mon not in mon_map:
        return None
    return (int(year), mon_map[mon])

rows=[]
with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for r in reader:
        rows.append(r)

# build monthly counts for keywords instead of major_topic
kw_month=defaultdict(Counter)
months=set()
for r in rows:
    m=parse_month_year(r.get('month_year'))
    if not m:
        continue
    months.add(m)
    kws=(r.get('keywords') or '').strip()
    if not kws:
        continue
    for kw in [k.strip() for k in kws.split(';') if k.strip()]:
        kw_month[kw][m]+=1

months=sorted(months)
# last 12 months
last=months[-1]
last12=[]
y,m=last
for _ in range(12):
    last12.append((y,m))
    m-=1
    if m==0:
        y-=1
        m=12
last12=sorted(last12)

scores=[]
for kw,c in kw_month.items():
    tot=sum(c.get(k,0) for k in last12)
    if tot<20:
        continue
    vals=[c.get(k,0) for k in last12]
    first=sum(vals[:6])
    lastp=sum(vals[6:])
    ratio=(lastp+1)/(first+1)
    scores.append((ratio, tot, kw, vals))

scores.sort(reverse=True)
print('candidates', len(scores))
for ratio, tot, kw, vals in scores[:15]:
    print(kw, 'ratio', round(ratio,2), 'tot', tot, 'first6', sum(vals[:6]), 'last6', sum(vals[6:]))
